import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule, ReactiveFormsModule, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { FinanceService, UserService } from '../../core/services/api.service';
import { DataTableComponent, TableColumn } from '../../shared/components/data-table.component';

@Component({
  selector: 'app-salaries',
  standalone: true,
  imports: [CommonModule, FormsModule, ReactiveFormsModule, DataTableComponent],
  template: `
    <div class="page-container">
      <div class="page-header">
        <div>
          <h3>👥 Gestion des Salariés</h3>
          <p class="subtitle">Suivi des contrats et paie</p>
        </div>
      </div>

      <!-- Stats -->
      <div class="stats-row" *ngIf="stats">
        <div class="stat-card">
          <strong>{{ stats.total }}</strong>
          <small>Total Salariés</small>
        </div>
        <div class="stat-card green">
          <strong>{{ stats.actifs }}</strong>
          <small>Actifs</small>
        </div>
        <div class="stat-card yellow">
          <strong>{{ stats.en_conge }}</strong>
          <small>En Congé</small>
        </div>
      </div>

      <app-data-table
        [columns]="columns" [data]="salaries" [loading]="loading"
        [totalCount]="totalCount" [currentPage]="currentPage"
        (search)="onSearch($event)" (pageChange)="onPageChange($event)"
        (edit)="onEdit($event)" (delete)="onDelete($event)">
      </app-data-table>

      <!-- Form Modal - Pour modifier les informations du salarié -->
      <div class="modal-overlay" *ngIf="showForm" (click)="closeForm()">
        <div class="modal-card" (click)="$event.stopPropagation()">
          <div class="modal-header">
            <h4>✏️ Modifier les informations du salarié</h4>
            <button class="close-btn" (click)="closeForm()">✕</button>
          </div>
          <form [formGroup]="form" (ngSubmit)="onSubmit()" class="modal-form">
            <!-- Informations du salarié sélectionné -->
            <div class="info-box" *ngIf="selectedSalarie">
              <strong>{{ selectedSalarie.user_nom }}</strong><br/>
              <small>{{ selectedSalarie.user_email }}</small>
            </div>
            
            <div class="form-row">
              <div class="form-group">
                <label>Type de Contrat</label>
                <select formControlName="type_contrat">
                  <option value="">Sélectionner</option>
                  <option *ngFor="let t of typesContrat" [value]="t.id">{{ t.nom }}</option>
                </select>
              </div>
              <div class="form-group">
                <label>Statut</label>
                <select formControlName="statut">
                  <option value="actif">Actif</option>
                  <option value="conge">En Congé</option>
                  <option value="licenciement">Licencié</option>
                  <option value="demission">Démission</option>
                </select>
              </div>
            </div>
            <div class="form-row">
              <div class="form-group">
                <label>Date d'embauche *</label>
                <input type="date" formControlName="date_embauche" />
              </div>
              <div class="form-group">
                <label>Salaire de base (FCFA) *</label>
                <input type="number" formControlName="salaire_base" min="0" />
              </div>
            </div>
            <div class="form-row">
              <div class="form-group">
                <label>Numéro CNPS</label>
                <input type="text" formControlName="numero_cnps" placeholder="N° CNPS" />
              </div>
              <div class="form-group">
                <label>Numéro Carte d'Identité</label>
                <input type="text" formControlName="numero_carte_identite" placeholder="N° CI" />
              </div>
            </div>
            <div class="form-row">
              <div class="form-group">
                <label>Banque</label>
                <input type="text" formControlName="banque" placeholder="Nom de la banque" />
              </div>
              <div class="form-group">
                <label>Numéro de Compte</label>
                <input type="text" formControlName="numero_compte" placeholder="Numéro de compte" />
              </div>
            </div>
            <div class="form-group">
              <label>Avantages en nature</label>
              <textarea formControlName="avantages" rows="2" placeholder="Voiture, téléphone, etc."></textarea>
            </div>
            <div class="modal-footer">
              <button type="button" class="btn btn-secondary" (click)="closeForm()">Annuler</button>
              <button type="submit" class="btn btn-primary" [disabled]="form.invalid || saving">
                {{ saving ? '...' : 'Enregistrer' }}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  `,
  styles: [`
    .stats-row { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 24px; }
    .stat-card { background: white; border-radius: 12px; padding: 16px 20px; border-left: 4px solid #e9ecef; box-shadow: 0 2px 8px rgba(0,0,0,0.05); }
    .stat-card.green { border-color: #10b981; }
    .stat-card.yellow { border-color: #f59e0b; }
    .stat-card strong { display: block; font-size: 18px; font-weight: 800; }
    .stat-card small { color: #999; font-size: 12px; }
    .info-box { background: #f8f9fa; padding: 12px; border-radius: 8px; margin-bottom: 16px; border-left: 3px solid #2563eb; }
    .info-box strong { color: #1a1a2e; }
    .info-box small { color: #666; }
  `]
})
export class SalariesComponent implements OnInit {
  salaries: any[] = [];
  users: any[] = [];
  typesContrat: any[] = [];
  loading = false;
  saving = false;
  totalCount = 0;
  currentPage = 1;
  searchTerm = '';
  showForm = false;
  editing: any = null;
  selectedSalarie: any = null;
  form!: FormGroup;
  stats: any = null;

  columns: TableColumn[] = [
    { key: 'user_nom', label: 'Nom' },
    { key: 'user_email', label: 'Email' },
    { key: 'type_contrat_nom', label: 'Contrat' },
    { key: 'salaire_base', label: 'Salaire Base', type: 'money' },
    { key: 'date_embauche', label: 'Embauche', type: 'date' },
    { key: 'statut_display', label: 'Statut', type: 'badge' },
    { key: 'actions', label: 'Actions', type: 'actions' }
  ];

  constructor(
    private financeService: FinanceService,
    private userService: UserService,
    private fb: FormBuilder
  ) {}

  ngOnInit(): void {
    this.load();
    this.loadUsers();
    this.loadTypesContrat();
  }

  load(): void {
    this.loading = true;
    this.financeService.salaries({ page: this.currentPage, search: this.searchTerm }).subscribe({
      next: d => { this.salaries = d.results; this.totalCount = d.count; this.loading = false; },
      error: () => { this.loading = false; }
    });
  }

  loadUsers(): void {
    this.userService.list().subscribe(d => this.users = d.results);
  }

  loadTypesContrat(): void {
    this.financeService.typesContrat().subscribe(d => this.typesContrat = d.results);
  }

  buildForm(d: any): void {
    this.selectedSalarie = d;
    this.form = this.fb.group({
      type_contrat: [d?.type_contrat || ''],
      date_embauche: [d?.date_embauche || '', Validators.required],
      salaire_base: [d?.salaire_base || 0, [Validators.required, Validators.min(0)]],
      numero_cnps: [d?.numero_cnps || ''],
      numero_carte_identite: [d?.numero_carte_identite || ''],
      banque: [d?.banque || ''],
      numero_compte: [d?.numero_compte || ''],
      avantages: [d?.avantages || ''],
      statut: [d?.statut || 'actif']
    });
  }

  onSearch(t: string): void { this.searchTerm = t; this.load(); }
  onPageChange(p: number): void { this.currentPage = p; this.load(); }
  openForm(d: any): void { this.editing = d; this.buildForm(d); this.showForm = true; }
  closeForm(): void { this.showForm = false; this.editing = null; this.selectedSalarie = null; }
  onEdit(d: any): void { this.openForm(d); }

  onDelete(d: any): void {
    if (confirm(`Supprimer le salarié "${d.user_nom}" ?`)) {
      this.financeService.deleteSalarie(d.id).subscribe(() => this.load());
    }
  }

  onSubmit(): void {
    if (this.form.invalid || !this.editing) return;
    this.saving = true;
    const data = this.form.value;
    
    this.financeService.updateSalarie(this.editing.id, data).subscribe({
      next: () => { this.saving = false; this.closeForm(); this.load(); },
      error: () => { this.saving = false; }
    });
  }
}
